1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Derives an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: the region code
11	 * derived from the owner's postcode joined to the first 8 upper-case hex characters of
12	 * SHA-256 over {@code (normalizedTelephone + lastName)}. The region segment also drives
13	 * the owner's locality, so both read from the same identity.
14	 */
15	public final class CustomerCodes {
16	
17	    private CustomerCodes() {
18	    }
19	
20	    /** The {@code '<REGION>-<HASH8>'} customer code for the given owner. */
21	    public static String of(Owner owner) {
22	        return Localities.regionOf(owner.getCity(), owner.getPostcode()) + "-"
23	            + hash8(owner.getTelephone() + owner.getLastName());
24	    }
25	
26	    /** The region segment of a customer code, or {@code "UNKNOWN"} when it is absent. */
27	    public static String regionOf(String customerCode) {
28	        if (customerCode == null) {
29	            return "UNKNOWN";
30	        }
31	        int dash = customerCode.indexOf('-');
32	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
33	    }
34	
35	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
36	    private static String hash8(String s) {
37	        try {
38	            byte[] digest = MessageDigest.getInstance("SHA-256")
39	                .digest(s.getBytes(StandardCharsets.UTF_8));
40	            StringBuilder sb = new StringBuilder(8);
41	            for (int i = 0; i < 4; i++) {
42	                sb.append(String.format("%02X", digest[i]));
43	            }
44	            return sb.toString();
45	        }
46	        catch (NoSuchAlgorithmException e) {
47	            throw new IllegalStateException(e);
48	        }
49	    }
50	}
