1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Collection;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey} and uses it as the single source of truth for
12	 * duplicate detection: the SHA-256 hex of
13	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
14	 *
15	 * <p>Two owners are duplicates only when their WHOLE identityKey matches; because the
16	 * telephone is part of the key, owners who share a last name and postcode but carry
17	 * different telephones have different keys and are both allowed (a soft match, not a 409).
18	 */
19	public final class IdentityKeys {
20	
21	    private IdentityKeys() {
22	    }
23	
24	    /** The owner's derived identity key. The telephone is already stored normalised
25	     *  (E.164); a missing email contributes an empty segment. */
26	    public static String of(Owner owner) {
27	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
28	        return sha256hex(owner.getTelephone() + "|" + email + "|" + Soundex.of(owner.getLastName()));
29	    }
30	
31	    /** Whether an existing owner shares the candidate's whole identity key. */
32	    public static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
33	        String key = of(candidate);
34	        return existing.stream().filter(o -> !o.isDeleted()).anyMatch(o -> key.equals(of(o)));
35	    }
36	
37	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
38	    private static String sha256hex(String s) {
39	        try {
40	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(digest.length * 2);
42	            for (byte b : digest) {
43	                sb.append(String.format("%02x", b));
44	            }
45	            return sb.toString();
46	        }
47	        catch (NoSuchAlgorithmException e) {
48	            throw new IllegalStateException(e);
49	        }
50	    }
51	}
