1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year helper: the fiscal year starts on 1 July and is named by the calendar
7	 * year in which it ends, so 1 July 2025 - 30 June 2026 is fiscal year 2026.
8	 */
9	public final class FiscalYears {
10	
11	    private FiscalYears() {
12	    }
13	
14	    /** The fiscal year that contains {@code date} (the calendar year it ends in). */
15	    public static int of(LocalDate date) {
16	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
17	    }
18	
19	    /** The two-digit last segment of the fiscal year for {@code date}, e.g. 26 for FY26. */
20	    public static int yearOfCentury(LocalDate date) {
21	        return of(date) % 100;
22	    }
23	
24	    /** The 'FY<YY>' label for {@code date}, e.g. FY26. */
25	    public static String label(LocalDate date) {
26	        return String.format("FY%02d", yearOfCentury(date));
27	    }
28	
29	    /** Whole fiscal years elapsed from {@code from} to {@code to}. */
30	    public static int elapsed(LocalDate from, LocalDate to) {
31	        return of(to) - of(from);
32	    }
33	}
