5	/**
6	 * Derives an owner's segment string {@code '<TIER>_<AREA>'}. TIER is {@code PREMIUM}
7	 * when the membership level is 3 or more, otherwise {@code STANDARD}. AREA is
8	 * {@code METRO} when the locality is a known region (NSW, VIC or QLD), otherwise
9	 * {@code REGIONAL}.
10	 */
11	public final class Segments {
12	
13	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
14	
15	    private Segments() {
16	    }
17	
18	    /** The {@code '<TIER>_<AREA>'} segment for the given membership level and locality. */
19	    public static String of(int membershipLevel, String locality) {
20	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
21	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
22	        return tier + "_" + area;
23	    }
24	}
