25	/**
26	 * Emits an audit trail entry when an {@link Owner} is created. On a successful
27	 * insert the {@code AUDIT} logger records the new owner's id, customer code and
28	 * registration date.
29	 */
30	public class OwnerAuditListener {
31	
32	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
33	
34	    private static final java.util.concurrent.atomic.AtomicLong OWNER_SEQ = new java.util.concurrent.atomic.AtomicLong();
35	
36	    @PostPersist
37	    void onCreate(Owner owner) {
38	        String membershipNumber = (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) ? null
39	            : owner.getCustomerCode() + "-M"
40	                + String.format("%02d", org.springframework.samples.petclinic.util.FiscalYears.yearOfCentury(owner.getRegistrationDate()));
41	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
42	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
43	            Membership.level(Membership.points(owner, false, false)), membershipNumber);
44	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"customerCode\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
45	            OWNER_SEQ.incrementAndGet(), owner.getId(), owner.getCustomerCode(),
46	            Membership.level(Membership.points(owner, false, false)));
47	    }
48	
49	}
