3	import java.lang.annotation.Documented;
4	import java.lang.annotation.ElementType;
5	import java.lang.annotation.Retention;
6	import java.lang.annotation.RetentionPolicy;
7	import java.lang.annotation.Target;
8	import java.util.Map;
9	
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.util.Localities;
12	
13	import jakarta.validation.Constraint;
14	import jakarta.validation.ConstraintValidator;
15	import jakarta.validation.ConstraintValidatorContext;
16	import jakarta.validation.Payload;
17	
18	/**
19	 * Class-level constraint on owner fields: when a 4-digit {@code postcode} is present it must
20	 * fall in the inclusive range for the city's region ({@link Localities#regionOf}). A city with
21	 * no known region, or an absent postcode, is accepted.
22	 */
23	@Target({ ElementType.TYPE })
24	@Retention(RetentionPolicy.RUNTIME)
25	@Constraint(validatedBy = PostcodeRegionValidator.class)
26	@Documented
27	public @interface PostcodeValidation {
28	
29	    String message() default "Postcode is not valid for the city's region";
30	
31	    Class<?>[] groups() default {};
32	
33	    Class<? extends Payload>[] payload() default {};
34	}
35	
36	/** Checks a supplied 4-digit postcode against its city region's inclusive range. */
37	class PostcodeRegionValidator implements ConstraintValidator<PostcodeValidation, OwnerFieldsDto> {
38	
39	    private static final Map<String, int[]> REGION_RANGE = Map.of(
40	        "NSW", new int[] { 2000, 2099 },
41	        "VIC", new int[] { 3000, 3099 },
42	        "QLD", new int[] { 4000, 4099 });
43	
44	    @Override
45	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
46	        String postcode = owner.getPostcode();
47	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
48	            return true;
49	        }
50	        int[] range = REGION_RANGE.get(Localities.regionOf(owner.getCity()));
51	        if (range == null) {
52	            return true;
53	        }
54	        int value = Integer.parseInt(postcode);
55	        return value >= range[0] && value <= range[1];
56	    }
57	}
